import type { ReactElement } from 'react'

/**
 * Coding Agent 官方品牌图标。
 *
 * 全部为官方发布的单色标记，SVG 用 fill="currentColor" 绘制，具体品牌色由 styles.css
 * 中的 .acc-logo.brand-<key> 规则给出（含暗色主题变体），因此图标天然适配明暗主题。
 *
 * 来源（均为官方单色 vector）：
 *   claude / cursor / codebuddy  → simple-icons
 *   codex                        → gilbarbara/logos（OpenAI Codex 应用图标）
 */
export interface BrandDef {
  title: string
  viewBox: string
  path: string
  /** true = 透明底字形（需落在中性底片上）；false = 自带方形底（如 Codex 应用图标） */
  glyph: boolean
  /** 在 34px 槽位内的渲染边长 */
  size: number
}

