/** 后端 key 是否已有官方品牌图标 */
export const hasBrand = (backend: string): boolean => !!BRANDS[backend]

/** 渲染单个官方品牌图标；未知后端返回 null（由调用方回退到字母底片） */
export function BrandMark({ backend, size }: { backend: string; size?: number }): ReactElement | null {
  const b = BRANDS[backend]
  if (!b) return null
  const s = size ?? b.size
  return (
    <svg
      className={`brand-svg brand-${backend}`}
      viewBox={b.viewBox}
      width={s}
      height={s}
      role="img"
      aria-label={b.title}
      focusable="false"
    >
      <path d={b.path} fill="currentColor" />
    </svg>
  )
}

/** 带图标的后端展示标签：官方图标 + 名称（未知后端仅显示名称） */
export function BackendLabel({ backend, name, iconSize = 14 }: { backend: string; name: string; iconSize?: number }) {
  return (
    <span className="backend-label">
      <BrandMark backend={backend} size={iconSize} />
      <span>{name}</span>
    </span>
  )
}
